import Foundation

/// The title Claude Code gives a session, read from its transcript
/// (~/.claude/projects/<project>/<session>.jsonl). `/rename` appends
/// {"type":"custom-title","customTitle":…}; the automatic title is
/// {"type":"ai-title","aiTitle":…}. Both may repeat; the last one counts.
struct ClaudeTitle: Equatable {
    /// Set by the user with /rename.
    var custom: String?
    /// Generated by Claude Code from the conversation.
    var ai: String?

    var best: String? { custom ?? ai }

    private struct Record: Decodable {
        let type: String
        let customTitle: String?
        let aiTitle: String?
    }

    /// Feeds complete lines of a transcript; later lines override earlier ones.
    mutating func scan(_ data: Data) {
        let decoder = JSONDecoder()
        for line in data.split(separator: UInt8(ascii: "\n")) {
            // Cheap filter: most lines are large messages that never hold a title.
            guard line.count < 4096,
                  let text = String(data: line, encoding: .utf8),
                  text.contains("-title\""),
                  let record = try? decoder.decode(Record.self, from: Data(line)) else { continue }
            switch record.type {
            case "custom-title":
                if let value = Self.clean(record.customTitle) { custom = value }
            case "ai-title":
                if let value = Self.clean(record.aiTitle) { ai = value }
            default:
                break
            }
        }
    }

    private static func clean(_ raw: String?) -> String? {
        let value = (raw ?? "").replacingOccurrences(of: "\n", with: " ").trimmingCharacters(in: .whitespacesAndNewlines)
        return value.isEmpty ? nil : String(value.prefix(160))
    }

    /// Reads the whole transcript of a session once, e.g. when opening a recent conversation.
    static func load(session: String) -> ClaudeTitle {
        var title = ClaudeTitle()
        if let url = transcript(for: session), let data = try? Data(contentsOf: url) { title.scan(data) }
        return title
    }

    static func transcript(for session: String) -> URL? {
        let projects = URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent(".claude/projects")
        for name in (try? FileManager.default.contentsOfDirectory(atPath: projects.path)) ?? [] {
            let url = projects.appendingPathComponent(name).appendingPathComponent(session + ".jsonl")
            if FileManager.default.fileExists(atPath: url.path) { return url }
        }
        return nil
    }

    /// The name a tab should get, or nil to keep its current one. An explicit /rename always
    /// wins once it changes; the automatic title never replaces a name the user typed in omux.
    static func nameUpdate(tabName: String, lastApplied: String?, title: ClaudeTitle) -> String? {
        guard let best = title.best, best != lastApplied else { return nil }
        if title.custom != nil { return best }
        return isDefaultName(tabName) || tabName == lastApplied ? best : nil
    }

    /// "Session" or "Session 3", as omux names new sessions.
    static func isDefaultName(_ name: String) -> Bool {
        guard name.hasPrefix("Session") else { return false }
        let rest = name.dropFirst("Session".count)
        return rest.isEmpty || (rest.first == " " && rest.dropFirst().allSatisfy(\.isNumber) && rest.count > 1)
    }
}

/// Copies Claude Code session titles into tab names while the
/// "Claude Session Name Inheritance" setting is on. Reads only what each
/// transcript gained since the last look.
@MainActor
final class ClaudeTitleMonitor {
    static let shared = ClaudeTitleMonitor()

    private let scanner = TitleScanner()
    private let queue = DispatchQueue(label: "omux.claude-titles", qos: .utility)
    private var scanning = false
    private var timer: Timer?

    private init() {}

    func start() {
        guard timer == nil else { return }
        timer = Timer.scheduledTimer(withTimeInterval: 3, repeats: true) { _ in
            Task { @MainActor in ClaudeTitleMonitor.shared.poll() }
        }
        poll()
    }

    func poll() {
        guard !scanning, UserDefaults.standard.bool(forKey: Prefs.inheritClaudeSessionName) else { return }
        let store = Store.shared
        let sessions = store.allTabs
            .filter { store.provider(of: $0.tab) == .claude }
            .map { (tab: $0.tab.id, session: $0.tab.claudeSessionID.uuidString.lowercased()) }
        guard !sessions.isEmpty else { return }
        scanning = true
        let scanner = self.scanner
        queue.async {
            let found = scanner.scan(sessions)
            DispatchQueue.main.async {
                self.scanning = false
                let store = Store.shared
                for (id, title) in found {
                    guard let tab = store.allTabs.first(where: { $0.tab.id == id })?.tab,
                          let name = ClaudeTitle.nameUpdate(tabName: tab.name, lastApplied: tab.claudeTitle, title: title)
                    else { continue }
                    store.applyClaudeTitle(id, name)
                }
            }
        }
    }
}

/// The file work behind ClaudeTitleMonitor. Only ever used on its serial queue.
private final class TitleScanner: @unchecked Sendable {
    private struct Progress {
        var url: URL
        var offset: UInt64 = 0
        var remainder = Data()
        var title = ClaudeTitle()
    }

    private var progress: [String: Progress] = [:]
    private var misses: [String: Date] = [:]

    func scan(_ sessions: [(tab: UUID, session: String)]) -> [UUID: ClaudeTitle] {
        var result: [UUID: ClaudeTitle] = [:]
        for entry in sessions {
            guard var state = state(for: entry.session) else { continue }
            read(&state)
            progress[entry.session] = state
            if state.title.best != nil { result[entry.tab] = state.title }
        }
        return result
    }

    private func state(for session: String) -> Progress? {
        if let state = progress[session] { return state }
        if let miss = misses[session], Date().timeIntervalSince(miss) < 10 { return nil }
        guard let url = ClaudeTitle.transcript(for: session) else {
            misses[session] = Date()
            return nil
        }
        return Progress(url: url)
    }

    private func read(_ state: inout Progress) {
        guard let size = (try? FileManager.default.attributesOfItem(atPath: state.url.path))?[.size] as? UInt64 else { return }
        if size < state.offset { state = Progress(url: state.url) } // rewritten: start over
        guard size > state.offset, let handle = try? FileHandle(forReadingFrom: state.url) else { return }
        defer { try? handle.close() }
        try? handle.seek(toOffset: state.offset)
        guard let chunk = try? handle.readToEnd(), !chunk.isEmpty else { return }
        state.offset += UInt64(chunk.count)
        var data = state.remainder + chunk
        // Keep a partial last line for the next read.
        if let last = data.lastIndex(of: UInt8(ascii: "\n")) {
            state.remainder = data[(last + 1)...].count < 1 << 20 ? Data(data[(last + 1)...]) : Data()
            data = Data(data[...last])
        } else {
            state.remainder = data.count < 1 << 20 ? data : Data()
            return
        }
        state.title.scan(data)
    }
}
